// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../../state.js";

/* Shared helpers for Agent M's print templates. Loaded before any template
 * module. Mirrors the el() / pageHeader() / gridTable() shape inside Agent
 * H's print_preview.js so the visual style stays uniform.
 */
(function () {
  "use strict";
  const APP = (window.APP = window.APP || {});
  const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === "class") n.className = attrs[k];
      else if (k === "html") n.innerHTML = attrs[k];
      else if (k.startsWith("on") && typeof attrs[k] === "function") n.addEventListener(k.slice(2), attrs[k]);
      else if (attrs[k] != null) n.setAttribute(k, attrs[k]);
    }
    for (const c of kids) {
      if (c == null) continue;
      n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
    }
    return n;
  }

  function page(landscape) {
    return el("div", {
      class: "chrx-preview-page",
      style: landscape
        ? "width:297mm;min-height:210mm;padding:10mm 12mm;background:#fff"
        : "background:#fff",
    });
  }

  function header(title, subtitle) {
    // aSc "print prefix": a line above the report title, typically the school.
    const s = (typeof window !== "undefined" && window.APP && window.APP.printSettings) || {};
    const prefix = s.headerPrefix ? String(s.headerPrefix) : "";
    return el("div", {
      style: "display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #333;padding-bottom:4px;margin-bottom:8px",
    },
      el("div", null,
        prefix ? el("div", { style: "font-size:8.5px;letter-spacing:.06em;text-transform:uppercase;color:#666;margin-bottom:2px" }, prefix) : null,
        el("h2", { style: "margin:0;font-size:14px" }, title || "")),
      el("div", { style: "font-size:9.5px;color:#555" }, subtitle || ""));
  }

  function footer() {
    return el("div", { style: "font-size:9px;color:#999;text-align:right;margin-top:8px" },
      "Chronexa · " + new Date().toLocaleDateString());
  }

  function emptyPage(msg) {
    const p = page();
    p.appendChild(header(msg || "No data", ""));
    return p;
  }

  function cardAtFor(list, day, period) {
    return (list || []).find(c => c.day === day && c.period === period) || null;
  }

  /**
   * What a printed cell shows — aSc's `ttreports.celltype`, driven by the
   * "What a cell shows" setting:
   *   subject (default) · subject-abbr · subject-teacher · teacher ·
   *   subject-room · group
   * One helper, so every template that prints a card follows the choice.
   */
  function cellTextMode() {
    const s = (typeof window !== "undefined" && window.APP && window.APP.printSettings) || {};
    return s.cellText || "subject";
  }

  function subjectLabel(card) {
    if (!card) return "";
    const subj = card.subjectAbbr || card.subject || "";
    const teacher = card.teacher || card.teacherName ||
      (Array.isArray(card.teachers) ? card.teachers.join(", ") : "");
    const room = card.classroom || card.classroomName || "";
    switch (cellTextMode()) {
      case "subject-abbr":  return card.subjectAbbr || card.subject || "";
      case "teacher":       return teacher || subj;
      case "subject-teacher": return teacher ? `${subj} · ${teacher}` : subj;
      case "subject-room":  return room ? `${subj} · ${room}` : subj;
      case "group":         return (Array.isArray(card.groups) && card.groups.length)
        ? card.groups.join(", ") : subj;
      default:              return subj;
    }
  }

  function teacherList(card) {
    return (card && card.teachers) ? card.teachers.join(", ") : "";
  }

  // Style block used by tables across templates (kept tiny so each template
  // can rely on identical look without redefining).
  function tableCSS() {
    return "border-collapse:collapse;width:100%;font-size:9.5px";
  }
  // W3b-1 — equal period columns. Under the default `table-layout:auto` the
  // browser sizes a column to its widest cell, so one slot holding "Sports
  // Meet Practice" plus 17 teacher names stretched its P4/P5 columns to ~3x
  // the width of P1-P3. `fixed` makes the declared (or, for width-less
  // <col>s, the equal-share) widths authoritative and wraps the content
  // inside its cell instead.
  function gridCSS() {
    return tableCSS() + ";table-layout:fixed";
  }
  // One <col> per column: the label column pinned to `labelWidth`, every
  // other column left width-less so table-layout:fixed hands them an
  // identical share of the remaining width. Pass the SAME sequence the
  // header row builds (periods, or days for the transposed structure).
  function gridCols(columns, labelWidth) {
    const cg = el("colgroup");
    cg.appendChild(el("col", { style: "width:" + (labelWidth || 62) + "px" }));
    (columns || []).forEach(() => cg.appendChild(el("col")));
    return cg;
  }
  // `overflow-wrap:anywhere` inherits into the cell's <div>s, so a long
  // teacher list breaks into the pinned column instead of widening it.
  const WRAP = ";overflow-wrap:anywhere;word-break:break-word;white-space:normal";
  function thCSS() {
    return "border:1px solid #888;background:#f0f0f0;padding:3px 5px;font-weight:600;text-align:left" + WRAP;
  }
  function tdCSS() {
    return "border:1px solid #bbb;padding:3px 5px;vertical-align:top" + WRAP;
  }

  // Item 5 — per-template structure resolver. Templates that want to
  // honour APP.printTemplateStructure overrides call this to learn
  // whether days should be rows (default) or columns. Inherits from
  // the global APP.printSettings.structure when no per-template
  // override is set. Returns "rows-days" or "columns-days".
  function structureFor(templateId) {
    const APP2 = window.APP || {};
    const perTpl = APP2.printTemplateStructure && APP2.printTemplateStructure[templateId];
    if (perTpl && perTpl !== "inherit") return perTpl;
    const global2 = (APP2.printSettings && APP2.printSettings.structure) || "rows-days";
    return global2;
  }

  APP.printTemplateUtils = {
    DAYS, el, page, header, footer, emptyPage,
    cardAtFor, subjectLabel, teacherList, cellTextMode,
    tableCSS, gridCSS, gridCols, thCSS, tdCSS,
    structureFor,
  };
})();
